mapper.select:
SELECT p.id, p.order_no, p.apply_no, p.apply_id, p.purchase_date, p.purchase_status, p.contract_no, p.supplier_id, p.supplier_name, p.total_amount, p.operator_id, p.operator_name, p.remark, p.create_user, p.create_time, p.update_time, COALESCE(e.emp_name, '') AS apply_emp_name, COALESCE(d.dept_name, '') AS apply_dept_name, COALESCE(od.dept_name, '') AS operator_dept_name, COALESCE(oe.emp_phone, '') AS operator_phone FROM asset_purchase p LEFT JOIN asset_purchase_apply_main a ON p.apply_id = a.id LEFT JOIN sys_emp e ON a.apply_emp_id = e.emp_id LEFT JOIN sys_dept d ON (a.apply_dept_id = CAST(d.dept_id AS CHAR) OR a.apply_dept_id = d.dept_code) LEFT JOIN sys_emp oe ON p.operator_id = oe.emp_id LEFT JOIN sys_dept od ON (oe.dept_id = od.dept_id OR (oe.dept_code IS NOT NULL AND oe.dept_code = od.dept_code)) WHERE 1=1
AND p.order_no LIKE CONCAT('%', #{orderNo}, '%')
AND p.apply_no LIKE CONCAT('%', #{applyNo}, '%')
AND p.purchase_status = #{purchaseStatus}
AND DATE(p.purchase_date) >= #{startDate}
AND DATE(p.purchase_date) <= #{endDate}
ORDER BY p.create_time DESC

mapper.update:
UPDATE asset_purchase
purchase_date = #{purchaseDate}, purchase_status = #{purchaseStatus}, contract_no = #{contractNo}, supplier_id = #{supplierId}, supplier_name = #{supplierName}, total_amount = #{totalAmount}, operator_id = #{operatorId}, operator_name = #{operatorName}, remark = #{remark},
WHERE id = #{id}
